import 'react-perfect-scrollbar/dist/css/styles.css';
import React, { useEffect, useRef } from 'react';
import { NavLink } from 'react-router-dom';
import { Nav } from 'reactstrap';
import PerfectScrollbar from 'react-perfect-scrollbar';
import colors from '../../config/colors';
import appRoutesList, { sidebarGroups } from '../../routes/AdminRoutes';
import { getLoggedUserUtils } from '../../utils/commonFunc';
import { isConfigAdmin, isFeatureEnabled } from '../../config/featureAccess';
import { Row, Col } from 'reactstrap';
import Tooltip from '@material-ui/core/Tooltip';
import { withStyles } from '@material-ui/core/styles';
import { store } from 'index';
import { makeFirstCaps } from 'config/constants';
import defaultLogo from 'assets/img/playstore_round.png';

// Fixed, not read from the per-school APP_THEME setting (see colors.js) - every school
// gets this same current sidebar look regardless of what's configured there.
const sidebarColor = colors.sidebarBg;
const sidebarLabelColor = colors.sidebarLabelColor;
const activeItemColor = colors.sidebarActiveItemBg;
const activeItemLabelColor = colors.accent;
const shadowOnActive = false;

// A short "what is this page for" note next to a menu item. MUI's default tooltip text is tiny, so it is made readable and
// capped in width. enterTouchDelay 0: on a touch screen a tap on the icon opens it straight away.
const HelpTooltip = withStyles({
  tooltip: { maxWidth: 240, fontSize: 12, lineHeight: 1.45, padding: '8px 10px', fontWeight: 'normal' },
})(Tooltip);

// The info icon only shows while its menu row is hovered (or the icon has keyboard focus), so the menu stays clean. A touch
// screen has no hover, so there it is always visible.
const helpIconCss = `
  .sidebar-wrapper li.sidebar-group-heading { list-style: none; padding: 16px 16px 8px; font-size: 11px; font-weight: bold;
    letter-spacing: 0.08em; text-transform: uppercase; color: ${sidebarLabelColor}; opacity: 0.6; }
  .sidebar-help-icon { opacity: 0; transition: opacity 0.15s ease; }
  .sidebar-wrapper li:hover .sidebar-help-icon, .sidebar-help-icon:focus { opacity: 0.7; }
  .sidebar-wrapper li .sidebar-help-icon:hover { opacity: 1; }
  @media (hover: none) { .sidebar-help-icon { opacity: 0.55; } }
`;

const Sidebar = props => {
  // The scrolling menu, so the selected item can be brought into view once, when the page is loaded or reloaded: the list
  // starts at the top, which hid the selected item whenever it sits far down. Not on later clicks - the menu stays where
  // the user left it.
  const scrollRef = useRef(null);
  useEffect(() => {
    const frame = requestAnimationFrame(() => {
      const container = scrollRef.current;
      const active = container?.querySelector('li.active');
      if (!container || !active) return;
      const offset = active.getBoundingClientRect().top - container.getBoundingClientRect().top;
      container.scrollTop = Math.max(
        0,
        container.scrollTop + offset - container.clientHeight / 2 + active.offsetHeight / 2
      );
    });
    return () => cancelAnimationFrame(frame);
  }, []);

  // Whole path segments only, so /admin/transport is not lit up by /admin/transport-reports.
  const matchesPath = routeName =>
    props.location.pathname === routeName || props.location.pathname.startsWith(`${routeName}/`);
  const activeRoute = item => {
    return matchesPath(item.path) || !!item.activeAliases?.some(matchesPath);
  };

  const schoolStore = store.getState()?.schools;
  const role = getLoggedUserUtils() ? getLoggedUserUtils().userRole : null;
  const activeStyle = {
    borderRadius: 5,
    backgroundColor: activeItemColor,
    fontWeight: 'bold',
    fontSize: 16,
    color: activeItemLabelColor,
    ...(!shadowOnActive && { border: `0.5px solid ${sidebarLabelColor}` }),
  };
  const inActiveStyle = { fontWeight: 'bold' };
  // Grouped by section (most-used section first), and most-used item first inside each section: see sidebarGroups and
  // the sidebarGroup / sidebarOrder of each route in routes/AdminRoutes.jsx.
  const groupIndex = key => {
    const index = sidebarGroups.findIndex(group => group.key === key);
    return index === -1 ? sidebarGroups.length : index;
  };
  const visibleItems = appRoutesList
    .filter(
      data =>
        data.sidebarView &&
        (data.accessRoles.includes('all') || data.accessRoles.includes(role)) &&
        isFeatureEnabled(data.feature, props.featureFlags) &&
        (!data.configAdminOnly || isConfigAdmin(props.loggedUserEmail))
    )
    .sort(
      (a, b) =>
        groupIndex(a.sidebarGroup) - groupIndex(b.sidebarGroup) || (a.sidebarOrder || 99) - (b.sidebarOrder || 99)
    )
    .map(item => ({ ...item, groupLabel: sidebarGroups.find(group => group.key === item.sidebarGroup)?.label }));
  return (
    <div
      className="sidebar"
      style={{
        background: sidebarColor,
        // boxShadow: "5px 0px 10px -2px #888"
      }}
      data-color={props.bgColor}
      data-active-color={props.activeColor}>
      <div
        className="d-flex align-items-center justify-content-start pl-5"
        style={{ background: colors.white, borderBottom: '1px solid #EADCF7', height: 59, boxSizing: 'border-box' }}>
        <img src={defaultLogo} alt="logo" width={35} height={35} />
        <a href="#" style={{ fontSize: 19, marginLeft: 10, color: colors.grey1 }}>
          <strong>{schoolStore?.school?.schoolShortName || 'DEMO'}</strong>
        </a>
      </div>

      <div className="sidebar-wrapper ml-2">
        <PerfectScrollbar options={{ suppressScrollX: true }} containerRef={el => (scrollRef.current = el)}>
          <style>{helpIconCss}</style>
          {/* room under the last item so it never sits against the bottom edge */}
          <Nav vertical style={{ paddingBottom: 96 }}>
            {visibleItems.map((item, i) => {
              const showHeading =
                !!item.groupLabel && (i === 0 || visibleItems[i - 1].sidebarGroup !== item.sidebarGroup);
              const isActive = activeRoute(item);
              // what the page is for: the role's own wording where the page shows less (or something else) to it
              const description = item.roleDescriptions?.[role] || item.description;
              return (
                <React.Fragment key={item.path}>
                  {showHeading && (
                    <li className="sidebar-group-heading" aria-hidden="true">
                      {item.groupLabel}
                    </li>
                  )}
                  <li className={isActive ? 'active mr-3' : 'mt-1 mb-1'}>
                    <NavLink
                      to={item.path}
                      className={`nav-link${isActive && shadowOnActive ? ' shadow' : ''}`}
                      activeClassName="active"
                      style={
                        isActive
                          ? { ...activeStyle, textTransform: 'none' }
                          : { ...inActiveStyle, textTransform: 'none' }
                      }>
                      <Row>
                        <Col md={2} sm={3} xs={3}>
                          {typeof item.icon === 'string' ? (
                            <i
                              className={item.icon}
                              aria-hidden="true"
                              style={{
                                fontSize: 18,
                                color: isActive ? activeItemLabelColor : sidebarLabelColor,
                              }}
                            />
                          ) : (
                            <span style={{ marginLeft: 5 }}>{item.icon}</span>
                          )}
                        </Col>
                        <Col md={10} sm={9} xs={9} style={{ position: 'relative' }}>
                          <div>
                            <span
                              style={{
                                fontSize: isActive ? 15 : 14,
                                color: isActive ? activeItemLabelColor : sidebarLabelColor,
                              }}>
                              <strong>{makeFirstCaps(item?.name)}</strong>
                            </span>
                            {!!description && (
                              <HelpTooltip
                                arrow
                                placement="right"
                                title={description}
                                enterDelay={200}
                                enterTouchDelay={0}
                                leaveTouchDelay={5000}>
                                <i
                                  className="fas fa-info-circle sidebar-help-icon"
                                  role="img"
                                  tabIndex={0}
                                  aria-label={`About ${makeFirstCaps(item?.name)}: ${description}`}
                                  // the icon sits inside the menu link: a click only shows the note, it does not open the page
                                  onClick={e => {
                                    e.preventDefault();
                                    e.stopPropagation();
                                  }}
                                  // Floats over the right edge of the row instead of sitting in it, so it never takes width from
                                  // the label (a long one such as "Generate time table" would otherwise wrap). The background
                                  // matches the row so, on the rare label that reaches the edge, it simply sits on top.
                                  style={{
                                    position: 'absolute',
                                    right: 8,
                                    top: '50%',
                                    transform: 'translateY(-50%)',
                                    width: 20,
                                    height: 20,
                                    lineHeight: '20px',
                                    textAlign: 'center',
                                    borderRadius: '50%',
                                    background: isActive ? activeItemColor : sidebarColor,
                                    fontSize: 13,
                                    cursor: 'pointer',
                                    color: isActive ? activeItemLabelColor : sidebarLabelColor,
                                  }}
                                />
                              </HelpTooltip>
                            )}
                          </div>
                        </Col>
                      </Row>
                    </NavLink>
                  </li>
                </React.Fragment>
              );
            })}
          </Nav>
        </PerfectScrollbar>
      </div>
    </div>
  );
};

export default Sidebar;
